import random
def start_blackjack_hand(player, bet, side_bets):
    deck = build_shoe(decks=6); random.shuffle(deck)
    player_cards = [deck.pop(), deck.pop()]
    dealer_cards = [deck.pop(), deck.pop()]  # second card hole
    for i, c in enumerate(player_cards):
        emit_animation_event('A6_CARD_DEAL', {'card': c, 'seat': 'player', 'delay_ms': i * 250})
    for i, c in enumerate(dealer_cards):
        emit_animation_event('A6_CARD_DEAL', {'card': c, 'seat': 'dealer', 'face_down': i == 1, 'delay_ms': 500 + i * 250})
    if side_bets.get('perfect_pairs'):
        result = resolve_perfect_pairs(player_cards, side_bets['perfect_pairs'])
        emit_animation_event('perfect_pairs_halo', {'tier': pair_tier(player_cards), 'win_units': result})
    if side_bets.get('twenty_one_plus_three'):
        result = resolve_21plus3(player_cards, dealer_cards[0], side_bets['twenty_one_plus_three'])
        emit_animation_event('21plus3_glow', {'win_units': result})
    return state.set_initial(deck, player_cards, dealer_cards, bet, side_bets)

