import random
def pikapokeri_deal_and_draw(player, bet, hold_indices):
    if state.phase == 'deal':
        deck = shuffled_52()
        hand = [deck.pop() for _ in range(5)]
        for i, c in enumerate(hand):
            emit_animation_event('A6_CARD_DEAL', {'card': c, 'index': i, 'delay_ms': i * 150})
        state.set_hand(hand, deck)
        return hand
    elif state.phase == 'draw':
        new_hand = []
        for i in range(5):
            if i in hold_indices:
                new_hand.append(state.hand[i])
            else:
                new_card = state.deck.pop()
                new_hand.append(new_card)
                emit_animation_event('A6_CARD_DEAL', {'card': new_card, 'index': i, 'replacement': True})
        category = evaluate_hand(new_hand)
        pay = PAYTABLE[category] * bet
        if pay > 0:
            emit_animation_event('A5_BIG_WIN' if pay >= 50*bet else 'A2_COIN_CASCADE', {'amount': pay})
            offer_double_up(pay)
        return {'hand': new_hand, 'category': category, 'pay': pay}

css_glsl_snippets.specular_highlight:
/* CSS — PBR-style specular gloss on a symbol surface (gel highlight) */
.symbol-pbr {
  position: relative;
  isolation: isolate;
}
.symbol-pbr::after {
  content: "";
  position: absolute;
  inset: 6% 8% 50% 12%;
  background: linear-gradient(160deg, rgba(255,255,255,0.78) 0%, rgba(255,255,255,0.18) 28%, rgba(255,255,255,0) 60%);
  mix-blend-mode: screen;
  pointer-events: none;
  filter: blur(0.6px);
  border-radius: 0;
}

css_glsl_snippets.rim_lighting:
/* CSS — rim-light on a winning symbol; uses two box-shadows offset opposite */
.symbol-rim-win {
  --rim-color: var(--accent-warning, #FFB800);
  outline: 1px solid #0A0A0A;
  box-shadow:
    inset 1px 1px 0 0 rgba(255,255,255,0.32),
    inset -1px -1px 0 0 rgba(0,0,0,0.42),
    0 0 0 2px var(--rim-color),
    0 0 16px 2px color-mix(in srgb, var(--rim-color) 70%, transparent);
  animation: rim-pulse 1100ms ease-in-out infinite alternate;
}
@keyframes rim-pulse {
  from { filter: drop-shadow(0 0 4px var(--rim-color)); }
  to   { filter: drop-shadow(0 0 14px var(--rim-color)); }
}

