/* CSS — coin with milled-edge specular ring */
.coin {
  width: 64px; height: 64px;
  background:
    radial-gradient(circle at 35% 30%, #FFE9A8 0%, #C9A227 38%, #5A4310 100%);
  border: 1px solid #0A0A0A;
  position: relative;
}
.coin::before {
  content: "";
  position: absolute; inset: -2px;
  background: repeating-conic-gradient(from 0deg, #2A1F08 0deg 4deg, #C9A227 4deg 8deg);
  mask: radial-gradient(circle, transparent 47%, #000 49%, #000 51%, transparent 53%);
  -webkit-mask: radial-gradient(circle, transparent 47%, #000 49%, #000 51%, transparent 53%);
  pointer-events: none;
}

css_glsl_snippets.particle_burst:
/* CSS — radial particle burst (12 spans cloned in a wrapper) */
.particle-burst { position: relative; width: 0; height: 0; }
.particle-burst > .p {
  position: absolute; left: 0; top: 0;
  width: 6px; height: 6px;
  background: var(--accent-warning, #FFB800);
  animation: burst 720ms cubic-bezier(0.22, 1, 0.36, 1) forwards;
}
.particle-burst > .p:nth-child(n) { --angle: calc(var(--i) * 30deg); }
@keyframes burst {
  0%   { transform: translate(0, 0) scale(1); opacity: 1; }
  100% { transform: rotate(var(--angle)) translateX(160px) scale(0.2); opacity: 0; }
}

css_glsl_snippets.reel_blur:
/* CSS — motion-blur on spinning reel column using filter + backdrop-fallback */
.reel-column.spinning {
  filter: blur(6px);
  will-change: transform, filter;
  transform: translate3d(0, var(--reel-y, 0), 0);
  transition: filter 220ms ease-out;
}
.reel-column.stopping {
  filter: blur(2px);
}
.reel-column.idle {
  filter: blur(0);
  transition: filter 120ms ease-out;
}
@supports (filter: blur(0)) {
  .reel-column { transform: translateZ(0); /* compositor hint */ }
}
